package cn.mop.api;
import cn.mop.domain.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class MonitoringScrapeObservationControllerTest {
    static final String TENANT=MonitoringScrapeObservationTest.TENANT,ACTOR="79000000-0000-4000-8000-000000000002";
    PlatformRepository repository;MonitoringPresetProbeService registered;MonitoringScrapeObservationController controller;MonitoringPresetRegistry.Target target;Asset asset;Membership member;AtomicInteger calls;
    @BeforeEach void setup(){repository=mock(PlatformRepository.class);var c=MonitoringScrapeObservationTest.config("linux-node",true);var registry=MonitoringPresetTest.registry(c);target=MonitoringPresetTest.first(registry,c);registered=new MonitoringPresetProbeService(registry,t->{throw new AssertionError("No direct probe allowed");},false);member=new Membership(ACTOR,TENANT,"padmin",7,true,List.of("assets:read","configurations:read"));when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(member));asset=new Asset(target.assetId(),TENANT,"Isolated unit fixture","other",target.assetIp(),"site","unknown","DRAFT","test_seed",null,null,1,Instant.EPOCH,Instant.EPOCH,null,null);when(repository.authorizedAsset(TENANT,ACTOR,7,target.assetId())).thenReturn(Optional.of(asset));calls=new AtomicInteger();reader((s,t,e)->{calls.incrementAndGet();return MonitoringScrapeObservationTest.bytes(MonitoringScrapeObservationTest.response(t,"1",MonitoringScrapeObservationTest.seconds(MonitoringScrapeObservationTest.NOW)));});}
    void reader(MonitoringScrapeObservationService.Reader r){var source=MonitoringScrapeObservationTest.source("http://127.0.0.1:9090/api/v1/query");controller=new MonitoringScrapeObservationController(repository,registered,new MonitoringScrapeObservationService(Map.of(TENANT,source),r,Clock.fixed(MonitoringScrapeObservationTest.NOW,ZoneOffset.UTC)));}
    MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/v1/monitoring-onboarding/registered-targets/"+target.id()+"/observation");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);return r;}
    @Test void readOnlyMemberReadsButNeverProbesAndScopeIsRechecked(){var data=(Map<?,?>)((Map<?,?>)controller.read(target.id(),request())).get("data");assertEquals("PROMETHEUS_SCRAPE_OBSERVATION",data.get("source"));assertEquals("SCRAPE_SUCCEEDED",((Map<?,?>)data.get("report")).get("observation_status"));assertEquals(1,calls.get());verify(repository,times(2)).authorizedAsset(TENANT,ACTOR,7,target.assetId());verify(repository,times(2)).membership(ACTOR,TENANT);}
    @Test void anonymousAndMissingCapabilityCannotRead(){var r=request();r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.read(target.id(),r)).status);when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true,List.of("assets:read"))));assertEquals(403,assertThrows(DomainException.class,()->controller.read(target.id(),request())).status);assertEquals(0,calls.get());}
    @Test void foreignMissingAndMalformedIdsDoNotRead(){for(String id:List.of("invalid",ACTOR))assertEquals(404,assertThrows(DomainException.class,()->controller.read(id,request())).status);assertEquals(0,calls.get());}
    @Test void destinationTenantQueriesAndBodiesAreForbidden(){for(String key:List.of("tenant_id","endpoint","query","time")){var r=request();r.addParameter(key,"override");assertEquals(400,assertThrows(DomainException.class,()->controller.read(target.id(),r)).status);}var r=request();r.setContent("{}".getBytes());assertEquals(400,assertThrows(DomainException.class,()->controller.read(target.id(),r)).status);assertEquals(0,calls.get());}
    @Test void oldAddressBindingCannotRead(){var changed=changed();when(repository.authorizedAsset(TENANT,ACTOR,7,target.assetId())).thenReturn(Optional.of(changed));assertEquals(404,assertThrows(DomainException.class,()->controller.read(target.id(),request())).status);assertEquals(0,calls.get());}
    Asset changed(){return new Asset(asset.id(),TENANT,asset.name(),asset.type(),"192.0.2.222",asset.siteId(),asset.status(),asset.lifecycleStatus(),asset.source(),null,null,2,Instant.EPOCH,Instant.EPOCH,null,null);}
    @Test void mutationDuringReadIsConflictNotStaleSuccess(){reader((s,t,e)->{when(repository.authorizedAsset(TENANT,ACTOR,7,target.assetId())).thenReturn(Optional.of(changed()));return MonitoringScrapeObservationTest.bytes(MonitoringScrapeObservationTest.response(t,"1",MonitoringScrapeObservationTest.seconds(e)));});assertEquals(409,assertThrows(DomainException.class,()->controller.read(target.id(),request())).status);}
    @Test void revokedMembershipAfterReadNeverReleasesData(){reader((s,t,e)->{when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.empty());return MonitoringScrapeObservationTest.bytes(MonitoringScrapeObservationTest.response(t,"1",MonitoringScrapeObservationTest.seconds(e)));});assertEquals(401,assertThrows(DomainException.class,()->controller.read(target.id(),request())).status);}
    @Test void missingRegistryReturnsPendingAndNoNetwork(){controller=new MonitoringScrapeObservationController(repository,new MonitoringPresetProbeService(null,t->{throw new AssertionError();},false),new MonitoringScrapeObservationService(Map.of(),(s,t,e)->{throw new AssertionError();},Clock.systemUTC()));assertEquals(503,assertThrows(DomainException.class,()->controller.read(target.id(),request())).status);assertEquals(0,calls.get());}
    @Test void privateCacheHeadersAreSet(){var r=new MockHttpServletResponse();controller.privateHeaders(r);assertEquals("no-store",r.getHeader("Cache-Control"));assertEquals("no-referrer",r.getHeader("Referrer-Policy"));}
}
